1830	        /* remove the query string part */
1831	        diff = qs - uri;
1832	        uri[diff] = '\0';
1833	    }
1834	
1835	    /* Compose the query string using the URI */
1836	    len = strlen(uri);
1837	
1838	    if (ctx->tag_from_uri != FLB_TRUE) {
1839	        tag = flb_sds_create(ctx->ins->tag);
1840	    }
1841	    else {
1842	        tag = flb_sds_create_size(len);
1843	        if (!tag) {
1844	            mk_mem_free(uri);
1845	            return -1;
1846	        }
1847	
1848	        /* New tag skipping the URI '/' */
1849	        flb_sds_cat(tag, uri + 1, len - 1);
1850	
1851	        /* Sanitize, only allow alphanum chars */
1852	        for (i = 0; i < flb_sds_len(tag); i++) {
1853	            if (!isalnum(tag[i]) && tag[i] != '_' && tag[i] != '.') {
1854	                tag[i] = '_';
1855	            }
1856	        }
1857	    }
1858	
1859	    tag_len = flb_sds_len(tag);
1860	
1861	    /* Check if we have a Host header: Hostname ; port */
1862	    mk_http_point_header(&request->host, &session->parser, MK_HEADER_HOST);
1863	
1864	    /* Header: Connection */
1865	    mk_http_point_header(&request->connection, &session->parser,
1866	                         MK_HEADER_CONNECTION);
1867	
1868	    /* HTTP/1.1 needs Host header */
