29	struct flb_opentelemetry *opentelemetry_config_create(struct flb_input_instance *ins)
30	{
31	    int ret;
32	    char port[8];
33	    struct flb_opentelemetry *ctx;
34	
35	    ctx = flb_calloc(1, sizeof(struct flb_opentelemetry));
36	    if (!ctx) {
37	        flb_errno();
38	        return NULL;
39	    }
40	    ctx->ins = ins;
41	    mk_list_init(&ctx->connections);
42	
43	    /* Load the config map */
44	    ret = flb_input_config_map_set(ins, (void *) ctx);
45	    if (ret == -1) {
46	        flb_free(ctx);
47	        return NULL;
48	    }
49	
50	    /* Listen interface (if not set, defaults to 0.0.0.0:4318) */
51	    flb_input_net_default_listener("0.0.0.0", OTLP_HTTP_PORT, ins);
52	
53	    ctx->listen = flb_strdup(ins->host.listen);
54	    snprintf(port, sizeof(port) - 1, "%d", ins->host.port);
55	    ctx->tcp_port = flb_strdup(port);
56	
57	    /* HTTP Server specifics */
58	    ctx->server = flb_calloc(1, sizeof(struct mk_server));
59	    ctx->server->keep_alive = MK_TRUE;
60	
61	    /* monkey detects server->workers == 0 as the server not being initialized at the
62	     * moment so we want to make sure that it stays that way!
63	     */
64	
65	    return ctx;
66	}
67	
68	int opentelemetry_config_destroy(struct flb_opentelemetry *ctx)
69	{
70	    /* release all connections */
71	    opentelemetry_conn_release_all(ctx);
72	
73	    if (ctx->collector_id != -1) {
74	        flb_input_collector_delete(ctx->collector_id, ctx->ins);
75	
76	        ctx->collector_id = -1;
77	    }
78	
79	    if (ctx->downstream != NULL) {
80	        flb_downstream_destroy(ctx->downstream);
81	    }
82	
83	    if (ctx->enable_http2) {
84	        flb_http_server_destroy(&ctx->http_server);
85	    }
86	
87	    if (ctx->server) {
88	        flb_free(ctx->server);
89	    }
90	
91	    flb_free(ctx->listen);
92	    flb_free(ctx->tcp_port);
93	    flb_free(ctx);
94	
95	    return 0;
96	}
