130	static int msgpack_strncmp(char* str, size_t str_len, msgpack_object obj)
131	{
132	    int ret = -1;
133	
134	    if (str == NULL) {
135	        flb_error("str is NULL");
136	        return -1;
137	    }
138	
139	    switch (obj.type)  {
140	    case MSGPACK_OBJECT_STR:
141	        if (obj.via.str.size != str_len) {
142	            return -1;
143	        }
144	        ret = strncmp(str, obj.via.str.ptr, str_len);
145	        break;
146	    case MSGPACK_OBJECT_POSITIVE_INTEGER:
147	        {
148	            unsigned long val = strtoul(str, NULL, 10);
149	            if (val == (unsigned long)obj.via.u64) {
150	                ret = 0;
151	            }
152	        }
153	        break;
154	    case MSGPACK_OBJECT_NEGATIVE_INTEGER:
155	        {
156	            long long val = strtoll(str, NULL, 10);
157	            if (val == (unsigned long)obj.via.i64) {
158	                ret = 0;
159	            }
160	        }
161	        break;
162	    case MSGPACK_OBJECT_FLOAT32:
163	    case MSGPACK_OBJECT_FLOAT64:
164	        {
165	            double val = strtod(str, NULL);
166	            if (fabs(val - obj.via.f64) < DBL_EPSILON) {
167	                ret = 0;
168	            }
169	        }
170	        break;
171	    case MSGPACK_OBJECT_BOOLEAN:
172	        if (obj.via.boolean) {
173	            if (str_len != 4 /*true*/) {
174	                return -1;
175	            }
176	            ret = strncasecmp(str, "true", 4);
177	        }
178	        else {
179	            if (str_len != 5 /*false*/) {
180	                return -1;
181	            }
182	            ret = strncasecmp(str, "false", 5);
183	        }
184	        break;
185	    default:
186	        flb_error("not supported");
187	    }
188	
189	    return ret;
190	}
